export function getSeasonFromDate(dateStr) {
  const [month, day] = dateStr.split('/').map(Number)
  const md = month * 100 + day
  if (md >= 101  && md <= 331)  return 'WINTER'
  if (md >= 401  && md <= 430)  return 'SPRING'
  if (md >= 501  && md <= 614)  return 'SUMMER_1'
  if (md >= 615  && md <= 831)  return 'SUMMER_2'
  if (md >= 901  && md <= 1231) return 'FALL'
  return 'WINTER'
}

export function getDaytypeFromDate(dateStr) {
  const [month, day, year] = dateStr.split('/').map(Number)
  const d = new Date(year, month - 1, day)
  const dow = d.getDay()
  return dow === 0 || dow === 6 ? 'WEEKEND' : 'WEEKDAY'
}

export function getLookupDefaults(routeId, direction, season, daytype) {
  const key = `${routeId}_${direction}_${season}_${daytype}`
  if (LOOKUP[key]) return LOOKUP[key]

  const altDaytype = daytype === 'WEEKDAY' ? 'WEEKEND' : 'WEEKDAY'
  const key2 = `${routeId}_${direction}_${season}_${altDaytype}`
  if (LOOKUP[key2]) return LOOKUP[key2]

  const key3 = `${routeId}_${direction}_WINTER_${daytype}`
  if (LOOKUP[key3]) return LOOKUP[key3]

  const prefix = `${routeId}_${direction}_`
  const fallback = Object.keys(LOOKUP).find(k => k.startsWith(prefix))
  if (fallback) return LOOKUP[fallback]

  return LOOKUP['ER_NB_WINTER_WEEKDAY']
}